import { BitmapFont, Button, Component, Graphics, Label, Layout, Mask, Node, RichText, Sprite, SpriteFrame, UIOpacity, UITransform, instantiate, sp } from 'cc';
import type { BetHistoryDetail } from '../../models/BetHistory';
import type { SlotRoundStep } from '../../models/SlotRound';
import type { SlotGrid } from '../../models/SlotGrid';
import AppAssetBundle from '../../utils/AppAssetBundle';
import GameConfigManager from '../../config/GameConfigManager';
import { CURRENCY_MAP, GAMEVIEWMAP } from '../../store/StoreMap';
import { SLOT_GAME_DEFINITION } from '../../config/SlotGameDefinition';

const VISUAL_COMPONENT_CLASSES: Array<new (...args: any[]) => Component> = [UITransform, Sprite, Label, Layout, Mask, Graphics, UIOpacity, RichText, sp.Skeleton];

function isVisualComponent(comp: Component): boolean {
    return VISUAL_COMPONENT_CLASSES.some((cls) => comp instanceof cls);
}

export default class HistoryAdapter {
    private readonly symbolsFolder = 'resources/Images/symbols';
    private readonly symbolCatalog = SLOT_GAME_DEFINITION.symbols;
    private static readonly VISIBLE_ROW_OFFSET = 2;

    private static readonly MULTIPLIER_FONT_PATH = 'resources/font/MU/num_mu';
    private static readonly MULTIPLIER_LABEL_FONT_SIZE = 36;

    private multiplierFont: BitmapFont | null = null;
    private historyRoundUnits: Node[] = [];
    private historyRoundIndex = 0;

    private resolveMulti(symbolId: number): string | undefined {
        const info = this.symbolCatalog.resolve(symbolId);
        return info.kind === 'multiplier' ? `${info.value}x` : undefined; // 6x
    }

    async getTable(data: any): Promise<Node> {
        const prefab = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(GAMEVIEWMAP.HISTORYTABLE.path);
        const node = instantiate(prefab) as Node;
        await this.fillTable(node, data);
        return node;
    }

    async getRoundDetail(data: BetHistoryDetail, isPortrait: boolean = false): Promise<Node> {
        const prefab = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(GAMEVIEWMAP.HISTORYROUNDDETAIL.path);
        const root = instantiate(prefab) as Node;
        const portraitWidth = 700;
        const setWidth = (unit: Node) => {
            if (!isPortrait) return;
            const ut = unit.getComponent(UITransform);
            if (ut) ut.width = portraitWidth;
        };

        const rounds = this.getMainHistoryRounds(data);
        const units = await Promise.all(rounds.map((round) => this.createNormalUnit(round.grid)));

        units.forEach((unit, index) => {
            setWidth(unit);
            this.setUnitWin(unit, data.summary.currency, rounds[index].win);
            this.bindHistoryRoundButtons(unit);
            this.updateHistoryRoundButtons(unit, index, units.length);
            unit.active = index === 0;
            root.addChild(unit);
        });

        this.historyRoundUnits = units;
        this.historyRoundIndex = 0;

        return root;
    }

    private async createNormalUnit(grid: SlotGrid | undefined): Promise<Node> {
        const unit = await this.loadRoundUnit();
        const tableContainer = unit.getChildByName('Table');
        const historyTable = tableContainer?.getChildByName('HistoryTable') ?? null;
        const historyBonusTable = tableContainer?.getChildByName('HistoryBonusTable') ?? null;
        if (historyBonusTable) historyBonusTable.active = false;
        if (historyTable) {
            historyTable.active = true;
            await this.fillGrid(historyTable, grid);
        }
        return unit;
    }

    private async loadRoundUnit(): Promise<Node> {
        const prefab = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(GAMEVIEWMAP.HISTORYROUNDUNIT.path);
        return instantiate(prefab) as Node;
    }

    private setUnitWin(unit: Node, currency: any, win: any, titleText?: string): void {
        const label = unit.getChildByName('TotalWin')?.getComponent(Label);
        if (label) label.string = `${CURRENCY_MAP[currency] ?? ''}${win ?? 0}`;
        if (titleText !== undefined) {
            const title = unit.getChildByName('TotalWinTitle')?.getComponent(Label);
            if (title) title.string = titleText;
        }
    }

    private async fillTable(node: Node, data: BetHistoryDetail | null | undefined): Promise<void> {
        await this.fillIconTable(node, this.toHistoryIconTable(data?.mainSteps[0]?.grid));
    }

    private async fillGrid(node: Node, grid: SlotGrid | undefined): Promise<void> {
        await this.fillIconTable(node, this.toHistoryIconTable(grid));
    }

    private async fillIconTable(node: Node, table: Array<{ symbol: string; col: number; row: number; multi?: string }>): Promise<void> {
        this.stripLogicComponents(node);
        const slotMachineView = node.getChildByName('SlotMachineView');
        if (!slotMachineView) return;

        for (const item of table) {
            if (!item.symbol) continue;
            const reel = slotMachineView.children[item.col];
            const container = reel?.getChildByName('Container');
            const posNode = container?.getChildByName(`pos${item.row + HistoryAdapter.VISIBLE_ROW_OFFSET}`);
            if (!posNode) continue;

            const spriteFrame = await this.getSprite(`${this.symbolsFolder}/${item.symbol}`);
            if (!spriteFrame || !posNode.isValid) continue;
            for (const child of [...posNode.children]) child.destroy();

            let sprite = posNode.getComponent(Sprite);
            if (!sprite) {
                sprite = posNode.addComponent(Sprite);
                sprite.sizeMode = Sprite.SizeMode.CUSTOM;
            }
            sprite.spriteFrame = spriteFrame;
            if (item.multi) await this.renderMultiplierLabel(posNode, item.multi);
        }
    }

    private toHistoryIconTable(grid: SlotGrid | null | undefined): Array<{ symbol: string; col: number; row: number; multi?: string }> {
        if (!grid) return [];
        return grid.columns.flatMap((column) =>
            column.symbolIds.map((symbolId, row) => ({
                symbol: this.symbolCatalog.frameName(symbolId),
                multi: this.resolveMulti(symbolId),
                col: column.index,
                row,
            })),
        );
    }

    private stripLogicComponents(node: Node): void {
        for (const comp of node.components.slice()) {
            if (!isVisualComponent(comp)) comp.destroy();
        }
        for (const child of node.children) this.stripLogicComponents(child);
    }

    private async getSprite(path: string): Promise<SpriteFrame | null> {
        const bundle = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).getBundle();
        return new Promise((resolve) => {
            bundle.load(`${path}/spriteFrame`, SpriteFrame, (err, asset) => {
                if (err) {
                    console.warn(`[HistoryAdapter] load sprite failed: ${path}`, err);
                    resolve(null);
                    return;
                }
                resolve(asset as SpriteFrame);
            });
        });
    }

    /** NG遊戲盤面 */
    private getMainHistoryRounds(data: BetHistoryDetail): readonly SlotRoundStep[] {
        return data.mainSteps;
    }

    /** FG遊戲盤面 確定後再接入 */
    private getFreeHistoryRounds(data: BetHistoryDetail): readonly (readonly SlotRoundStep[])[] {
        return data.freeRounds;
    }

    /** 上一盤 */
    public showPreviousHistoryRound(): void {
        this.showHistoryRound(this.historyRoundIndex - 1);
    }

    /** 下一盤 */
    public showNextHistoryRound(): void {
        this.showHistoryRound(this.historyRoundIndex + 1);
    }

    private bindHistoryRoundButtons(unit: Node): void {
        const table = unit.getChildByName('Table');
        const previousButton = table?.getChildByName('PreviousButton');
        const nextButton = table?.getChildByName('NextButton');

        previousButton?.on(Button.EventType.CLICK, this.showPreviousHistoryRound, this);
        nextButton?.on(Button.EventType.CLICK, this.showNextHistoryRound, this);
    }

    private showHistoryRound(index: number): void {
        const total = this.historyRoundUnits.length;
        if (total === 0) return;

        this.historyRoundIndex = Math.min(Math.max(index, 0), total - 1);
        this.historyRoundUnits.forEach((unit, unitIndex) => {
            unit.active = unitIndex === this.historyRoundIndex;
            this.updateHistoryRoundButtons(unit, unitIndex, total);
        });
    }

    private updateHistoryRoundButtons(unit: Node, index: number, total: number): void {
        const table = unit.getChildByName('Table');
        const previousButton = table?.getChildByName('PreviousButton');
        const nextButton = table?.getChildByName('NextButton');

        if (previousButton) previousButton.active = index > 0;
        if (nextButton) nextButton.active = index < total - 1;
    }

    private async getMultiplierFont(): Promise<BitmapFont | null> {
        if (this.multiplierFont) return this.multiplierFont;
        const bundle = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).getBundle();
        return new Promise((resolve) => {
            bundle.load(HistoryAdapter.MULTIPLIER_FONT_PATH, BitmapFont, (err, asset) => {
                if (err) {
                    console.warn(`[HistoryAdapter] load font failed: ${HistoryAdapter.MULTIPLIER_FONT_PATH}`, err);
                    resolve(null);
                    return;
                }
                this.multiplierFont = asset as BitmapFont;
                resolve(this.multiplierFont);
            });
        });
    }

    /** 沒有prefab 容器會直接清空 label直接疊上去 */
    private async renderMultiplierLabel(posNode: Node, multi: string): Promise<void> {
        const font = await this.getMultiplierFont();

        const labelNode = new Node('MultiplierLabel');
        labelNode.addComponent(UITransform);
        const label = labelNode.addComponent(Label);
        label.string = multi;
        label.fontSize = HistoryAdapter.MULTIPLIER_LABEL_FONT_SIZE;
        label.horizontalAlign = Label.HorizontalAlign.CENTER;
        label.verticalAlign = Label.VerticalAlign.CENTER;
        if (font) {
            label.useSystemFont = false;
            label.font = font;
        }
        posNode.addChild(labelNode);
    }
}
