import { Tween } from 'cc';
import { GameTask } from './GameTask';
import { SlotMachineState } from '../reel/model/SlotMachineModel';
import type { SlotFreeMultiplierStep, SlotRoundStep } from '../models/SlotRound';
import { matchMinWinTier } from '../config/GameConst';
import PresentationStore from '../config/PresentationStore';
import { runCascadeReels } from './CascadeReelsTask';
import { runCollectWin } from './CollectWinTask';
import { WinAnimationView } from '../ui/WinAnimationView';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';

/**
 * 免費遊戲單局動畫段：
 * 轉輪/收球邏輯直接呼叫 runCascadeReels()/runCollectWin()（與主流程的
 * CascadeReelsTask/CollectWinTask 共用同一份實作，不重複寫）。
 * rollWinBalance() 仍留在 GameMain_1001（它的 debounce 計時器欄位跨多次呼叫共用同一顆，
 * 屬於 GameMain 狀態，不宜搬進每局都重新建立的 Task 實體）。
 * 匯出成函式是因為玩家端 API 的免費遊戲每一轉在播放時才取得，要逐轉呼叫。
 */
export async function runFreeRound(
    game: ISlotGameMain<GameViewAdapter>,
    steps: readonly SlotRoundStep[],
    freeMul: SlotFreeMultiplierStep | undefined
): Promise<void> {
    // 每一轉開放快停與跳過
    game.openSpinWindow();
    try {
        await runFreeRoundBody(game, steps, freeMul);
    } finally {
        game.closeSpinWindow();
    }
}

async function runFreeRoundBody(
    game: ISlotGameMain<GameViewAdapter>,
    steps: readonly SlotRoundStep[],
    freeMul: SlotFreeMultiplierStep | undefined
): Promise<void> {
    game.slotMachineModel.setState(SlotMachineState.IDLE);
    game.onNormalSpin();
    Tween.stopAllByTarget(game.winBarProxy);
    game.winBarValue = 0;
    game.winBarProxy.v = 0;
    game.setWinBarNum(0);
    await new Promise<void>((r) => game.scheduleOnce(r, 0.25));
    const fgCols = await runCascadeReels(game, steps);
    // 該局贏分：free_multipliers[i].win（已套累積倍率）優先，否則該局各 step win 加總
    const roundWin = freeMul?.win !== undefined ? Number(freeMul.win) || 0 : steps.reduce((s, st) => s + (Number(st.win) || 0), 0);
    // 收球：該局有贏分且有倍率球(multiplier>0)時收，accumulated=累積計數器值（API §5.4-4）
    if (fgCols && freeMul && freeMul.multiplier > 0 && roundWin > 0) {
        await runCollectWin(game, fgCols, freeMul.accumulated || 0, true, roundWin);
    }

    await playRoundWinAnimation(game, roundWin);

    game.fgTotalWin += roundWin;
    game.freeSpinsRemaining = Math.max(0, game.freeSpinsRemaining - 1);
    game.updateFgUi();
    if (roundWin > 0) {
        await game.rollWinBalance(game.fgTotalWin, 0.4);
    } else {
        game.storeManager.getModel('TemplateStore').setWinBalance(Number(game.fgTotalWin.toFixed(2)));
    }
}

/** 依門檻跳報獎彈窗 未達標不報獎 */
async function playRoundWinAnimation(game: ISlotGameMain<GameViewAdapter>, roundWin: number): Promise<void> {
    const config = PresentationStore.getInstance().config;
    if (!config.featureRoundWinPresentationEnabled || roundWin <= 0) return;
    const bet = game.storeManager.getModel('TemplateStore').betBalance;
    const tier = WinAnimationView.getWinKey(roundWin, bet);
    if (!matchMinWinTier(tier, config.featureRoundWinPresentationMinTier)) return;
    await game.popups.showWinAnimation(roundWin, bet);
}

/** 免費遊戲單局動畫段的 Task 殼，addTask() 到頂層佇列時使用（mock 的整局資料走這個） */
export class PlayFreeRoundTask extends GameTask {
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly steps: readonly SlotRoundStep[],
        private readonly freeMul: SlotFreeMultiplierStep | undefined
    ) {
        super();
    }

    protected onStart(): void {
        runFreeRound(this.game, this.steps, this.freeMul)
            .catch((error) => console.warn('[PlayFreeRoundTask] failed', error))
            .finally(() => this.finish());
    }
}
